-- One owner per address, for good (reverses PR #169's many accounts per address), and with it no `removed`
-- status: a link no longer ends. Generated by drizzle-kit, then the trigger was added by hand.
-- This converts no rows, because no signed link exists yet, and it stops rather than guesses if one does: a
-- `linked` row fails the new check and a `removed` one the new enum. Clear the table right before applying it,
-- pending rows too: those apply cleanly but keep the old signing text, without the sentence that the link is for good.
-- Code from before it cannot read the table (no `removed_at`) or link (no `ops_request`): apply it and promote the
-- code together, a rollback past it needs the column back, and previews of older branches fail on a database that has it.
CREATE TYPE "public"."wallet_link_ops_request" AS ENUM('whitelist', 'revoke');--> statement-breakpoint
ALTER TABLE "wallet_link" ADD COLUMN "ops_request" "wallet_link_ops_request";--> statement-breakpoint
ALTER TABLE "wallet_link" ADD COLUMN "ops_request_version" integer DEFAULT 0 NOT NULL;--> statement-breakpoint
ALTER TABLE "wallet_link" DROP COLUMN "removed_at";--> statement-breakpoint
DROP INDEX "wallet_link_linked_user_address_uidx";--> statement-breakpoint
DROP INDEX "wallet_link_pending_user_address_uidx";--> statement-breakpoint
ALTER TABLE "wallet_link" DROP CONSTRAINT "wallet_link_linked_has_signature";--> statement-breakpoint
ALTER TYPE "public"."wallet_link_status" RENAME TO "wallet_link_status_old";--> statement-breakpoint
CREATE TYPE "public"."wallet_link_status" AS ENUM('pending', 'linked');--> statement-breakpoint
ALTER TABLE "wallet_link" ALTER COLUMN "status" TYPE "public"."wallet_link_status" USING "status"::text::"public"."wallet_link_status";--> statement-breakpoint
DROP TYPE "public"."wallet_link_status_old";--> statement-breakpoint
CREATE UNIQUE INDEX "wallet_link_linked_address_uidx" ON "wallet_link" USING btree ("address") WHERE "wallet_link"."status" = 'linked';--> statement-breakpoint
CREATE UNIQUE INDEX "wallet_link_pending_user_address_uidx" ON "wallet_link" USING btree ("user_id","address") WHERE "wallet_link"."status" = 'pending';--> statement-breakpoint
ALTER TABLE "wallet_link" ADD CONSTRAINT "wallet_link_linked_has_signature" CHECK ("wallet_link"."status" = 'pending' OR ("wallet_link"."signature" IS NOT NULL AND "wallet_link"."signed_at" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "wallet_link" ADD CONSTRAINT "wallet_link_linked_has_ops_request" CHECK ("wallet_link"."status" <> 'linked' OR ("wallet_link"."ops_request" IS NOT NULL AND "wallet_link"."ops_request_version" > 0));--> statement-breakpoint
-- A linked row is never deleted — so a user who owns an address cannot be deleted either (the foreign key's
-- cascade runs into this) — never leaves `linked`, and never changes hands, address or proof.
CREATE FUNCTION "wallet_link_guard_signed"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD."status" = 'linked' THEN
      RAISE EXCEPTION 'wallet_link %: a signed link is never deleted', OLD."id" USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD."status" = 'linked' AND (
    NEW."status", NEW."user_id", NEW."address", NEW."chain_id", NEW."nonce", NEW."typed_data",
    NEW."signature", NEW."signed_at", NEW."issued_at", NEW."expires_at"
  ) IS DISTINCT FROM (
    OLD."status", OLD."user_id", OLD."address", OLD."chain_id", OLD."nonce", OLD."typed_data",
    OLD."signature", OLD."signed_at", OLD."issued_at", OLD."expires_at"
  ) THEN
    RAISE EXCEPTION 'wallet_link %: a signed link keeps its status, owner, address and proof', OLD."id"
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER "wallet_link_guard_signed" BEFORE UPDATE OR DELETE ON "wallet_link"
FOR EACH ROW EXECUTE FUNCTION "wallet_link_guard_signed"();
